CREATE OR REPLACE FUNCTION update_player_market_value()
RETURNS TRIGGER AS $$
BEGIN
UPDATE player
SET market_value = NEW.transfer_fee_usd
WHERE id = NEW.player_id;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_update_player_market_value ON transfer;

CREATE TRIGGER trg_update_player_market_value
  AFTER INSERT OR UPDATE ON transfer
                    FOR EACH ROW
                    EXECUTE FUNCTION update_player_market_value();
